const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a representative bounding box for a section of the Great Plains, US
  // This covers parts of Nebraska, Kansas, Iowa, and Missouri.
  const geometry = ee.Geometry.Rectangle([-100, 37, -90, 43]);

  const year2003 = 2003;
  const year2019 = 2019;

  // CDL Class Codes for desired crops
  const cornCode = 1;
  const soybeanCode = 5;
  const wheatCodes = [3, 4, 24]; // 3: Winter Wheat, 4: Spring Wheat, 24: Durum Wheat

  // Function to process CDL for a given year
  const getCropArea = (year) => {
    const cdl = ee.ImageCollection('USDA/NASS/CDL')
      .filter(ee.Filter.date(`${year}-01-01`, `${year}-12-31`));

    const imageCollectionSize = cdl.size().getInfo();
    if (imageCollectionSize === 0) {
      console.log(`No CDL image found for year ${year}.`);
      return null;
    }

    const cdlImage = cdl.first().select('cropland');

    // Create a binary mask for corn, wheat, and soybeans
    const cornMask = cdlImage.eq(cornCode);
    const soybeanMask = cdlImage.eq(soybeanCode);
    // Combine all wheat types
    let wheatMask = cdlImage.eq(wheatCodes[0]);
    for (let i = 1; i < wheatCodes.length; i++) {
      wheatMask = wheatMask.or(cdlImage.eq(wheatCodes[i]));
    }

    // Combine all three crop types
    const combinedCropMask = cornMask.or(soybeanMask).or(wheatMask);

    // Calculate the number of pixels where these crops are present
    // Use a large scale (e.g., 3000m) to avoid memory issues and ensure faster computation
    // CDL resolution is 30m, so pixel area is 30*30 = 900 sq meters.
    const pixelCount = combinedCropMask.reduceRegion({
      reducer: ee.Reducer.sum(), // Sum of 1s (crop pixels)
      geometry: geometry,
      scale: 30, // Use original resolution for accurate pixel count
      maxPixels: 1e10, // Increase maxPixels for large regions
      tileScale: 4 // Adjust tileScale for memory management
    }).get('cropland');

    return ee.Number(pixelCount);
  };

  // 2. Data Acquisition & Check
  const pixelCount2003 = await ee.data.computePromise(getCropArea(year2003));
  const pixelCount2019 = await ee.data.computePromise(getCropArea(year2019));

  if (pixelCount2003 === null || pixelCount2019 === null) {
    console.log("Empty Collection detected for one or both years.");
    console.log("C1");
    return;
  }

  const area2003SqKm = pixelCount2003 * (30 * 30) / 1e6; // Convert pixels to square kilometers
  const area2019SqKm = pixelCount2019 * (30 * 30) / 1e6; // Convert pixels to square kilometers

  // 3. Processing & 4. Calculation
  // Check for valid pixels (C2)
  if (pixelCount2003 === 0 && pixelCount2019 === 0) {
    console.log("No valid pixels found for crops in either year within the specified geometry after processing.");
    console.log("C2");
    return;
  }

  // Check for calculation failures (C3)
  if (area2003SqKm === null || isNaN(area2003SqKm) ||
      area2019SqKm === null || isNaN(area2019SqKm)) {
    console.log("Calculation resulted in None/NaN.");
    console.log("C3");
    return;
  }

  // 5. Validation & Final Answer
  console.log(`Corn, Wheat, Soybean area in 2003: ${area2003SqKm.toFixed(2)} sq km`);
  console.log(`Corn, Wheat, Soybean area in 2019: ${area2019SqKm.toFixed(2)} sq km`);

  if (area2019SqKm > area2003SqKm) {
    console.log("A"); // Yes, there is an increase
  } else {
    console.log("B"); // No, there is no increase (includes decrease or no change)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
